module Main;
function main(): void {
  for (let i: byte = 0 to 39) { poke($0400 + i, 32); }
}

module Main;
const BORDER: word = $D020;
function main(): void {
  poke(BORDER, 5);
}

module Main;
function main(): void {
  poke($0400 + 5, 1);
}

module Main;
const PLAY: word = $1003;
function main(): void {
  let f: word = PLAY;
  f();
}

module Main;
struct Spr { x: byte; y: byte; }
let sprites: Spr[4];
function main(): void {
  let i: byte = 1;
  let tmp: Spr = sprites[i];
  poke($D000, tmp.x);
}

module Main;
let map: byte[25][40];
function main(): void {
  let x: byte = 1;
  let y: byte = 2;
  poke($D020, map[<word>(y)][x]);
}

module Main;
let buf: byte[8];
function main(): void {
  for (let i: byte = 0 until 8) { buf[i] = 0; }
}

module Main;
function main(): void {
  let w: word = 300;
  let b: byte = byte(w);
  poke($D020, b);
}

module Main;
function main(): void {
  let x: byte = peek($D012);
  let h: byte = x / 2;
  poke($D020, h);
}

module Main;
const STRIDE: byte = 2;
function main(): void {
  for (let i: byte = 0 to 10 step STRIDE) { poke($D020, i); }
}
